#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set the two totals to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Wizard knobs (env overrides, handy for CI/dry runs):
#   SKIP_INSTALL=1 — skip mise install + pnpm install/build
#   SKIP_MISE=1    — skip only the mise toolchain install
#   SKIP_GITHUB=1  — skip gist creation, GitHub repo, and CI secrets

TEMPLATE_KIND=""
TEMPLATE_DIR=""
PKG_NAME=""
DISPLAY_NAME=""
CREATOR_ID=""
GH_OWNER=""
GH_REPO=""
UNIVERSE_ID=""
PLACE_ID=""
ROBLOX_OPEN_CLOUD_API_KEY=""
BEDROCK_API_KEY=""
ASPHALT_API_KEY=""
BEDROCK_GITHUB_TOKEN=""
GIST_SECRET=""
BADGE_GIST_ID=""
BEDROCK_GIST_ID=""
NPM_TOKEN=""
AGENT_CONFIG_DIR=""
WZ_SCOPE=""
WZ_BARE=""

looks_like_game()   { [[ -f default.project.json && -f bedrock.config.ts && -f asphalt.toml ]]; }
looks_like_package(){ [[ -d packages/example && -d .changeset ]]; }

detect_template() {
  if   looks_like_game;   then TEMPLATE_KIND="game"
  elif looks_like_package; then TEMPLATE_KIND="package"
  fi
}

normalize_path() {
  local p="$1"
  p="${p//\\//}"
  p="${p#\"}"; p="${p%\"}"
  printf '%s' "$p"
}

slugify() {
  printf '%s' "$1" | tr '[:upper:]' '[:lower:]' \
    | sed -e 's/[^a-z0-9._-]/-/g' -e 's/-\{2,\}/-/g' -e 's/^-//' -e 's/-$//'
}

# wz_run CMD... — run through mise when available so pinned tool versions win.
wz_run() {
  if command -v mise >/dev/null 2>&1; then mise exec -- "$@"; else "$@"; fi
}

# wz_sed_inplace EXPR FILE... — portable in-place sed (macOS vs GNU).
wz_sed_inplace() {
  local expr="$1"; shift
  if [[ "$(uname -s)" == Darwin ]]; then sed -i '' "$expr" "$@"; else sed -i "$expr" "$@"; fi
}

# Escape & \ | in a string used as a sed replacement with | delimiters.
wz_sed_escape() {
  printf '%s' "$1" | sed -e 's/[\\&|]/\\&/g'
}

detect_studio() {
  case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
      [[ -d "/c/Program Files (x86)/Roblox/Versions" || -d "/c/Program Files/Roblox/Versions" ]] ;;
    Darwin) [[ -d "/Applications/RobloxStudio.app" ]] ;;
    *) [[ -d "$HOME/.local/share/roblox" || -d "$HOME/.var/app/org.vinegarhq.Vinegar/data/vinegar" ]] ;;
  esac
}

# create_secret_gist DESC FILENAME CONTENT → prints the gist id, or empty.
create_secret_gist() {
  local desc="$1" fname="$2" content="$3" out id
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    out=$(printf '%s\n' "$content" | gh gist create -f "$fname" -d "$desc" - 2>/dev/null || true)
    id=$(printf '%s\n' "$out" | sed -nE 's#^.*/([0-9a-f]+)/?$#\1#p' | head -n1)
    [[ -n "$id" ]] && { printf '%s' "$id"; return 0; }
  fi
  return 1
}

rename_game() {
  say "Replacing template names in config and source…"
  wz_sed_inplace "s|rbxts-game-template|$PKG_NAME|g" \
    package.json \
    default.project.json \
    bedrock.config.ts \
    src/server/centurion/commands/example.ts \
    src/client/ui/hud/session/sessionHud.render.tsx \
    src/client/ui/hud/session/tests/sessionHud.render.spec.tsx
  if [[ -n "$DISPLAY_NAME" ]]; then
    local r
    r=$(wz_sed_escape "$DISPLAY_NAME")
    wz_sed_inplace "s|displayName: \"$PKG_NAME\"|displayName: \"$r\"|" bedrock.config.ts
  fi
  if [[ -n "$UNIVERSE_ID" ]]; then
    wz_sed_inplace "s|universeId: \"0\"|universeId: \"$UNIVERSE_ID\"|" bedrock.config.ts
  fi
  if [[ -n "$PLACE_ID" ]]; then
    wz_sed_inplace "s|placeId: \"0\"|placeId: \"$PLACE_ID\"|" bedrock.config.ts
  fi
  if [[ -n "$BEDROCK_GIST_ID" ]]; then
    wz_sed_inplace "s|gistId: \"\"|gistId: \"$BEDROCK_GIST_ID\"|" bedrock.config.ts
  fi
  if [[ -n "$CREATOR_ID" ]]; then
    wz_sed_inplace "s|id = 0|id = $CREATOR_ID|" asphalt.toml
    wz_sed_inplace "s|const OWNER = 0;|const OWNER = $CREATOR_ID;|" src/server/server.server.ts
  fi
  say "Done."
  warn "Still manual: README badge links, AGENTS.md text, developer products in bedrock.config.ts."
}

rename_package() {
  local scope="$WZ_SCOPE" bare="$WZ_BARE" test_name
  if [[ -n "$scope" ]]; then test_name="${scope}/test-${bare}"; else test_name="test-${bare}"; fi
  say "Renaming packages/example → packages/$bare and test/example → test/$bare…"
  if [[ -d "packages/example" && "$bare" != "example" ]]; then
    git mv packages/example "packages/$bare" 2>/dev/null || mv packages/example "packages/$bare"
  fi
  if [[ -d "test/example" && "$bare" != "example" ]]; then
    git mv test/example "test/$bare" 2>/dev/null || mv test/example "test/$bare"
  fi
  export WZ_PKG_NAME="$PKG_NAME"
  export WZ_TEST_NAME="$test_name"
  export WZ_SCOPE="$scope"
  export WZ_BARE="$bare"
  export WZ_GH_OWNER="$GH_OWNER"
  export WZ_GH_REPO="$GH_REPO"
  wz_run node -e '
const fs = require("fs");
const e = process.env;
const scope = e.WZ_SCOPE || "";
const bare = e.WZ_BARE;
const pkgName = e.WZ_PKG_NAME;
const testName = e.WZ_TEST_NAME;
const repoUrl = "https://github.com/" + e.WZ_GH_OWNER + "/" + e.WZ_GH_REPO;
const read = (f) => JSON.parse(fs.readFileSync(f, "utf8"));
const write = (f, o) => fs.writeFileSync(f, JSON.stringify(o, null, "\t") + "\n");
const root = read("package.json");
root.name = e.WZ_GH_REPO;
write("package.json", root);
const pkg = read("packages/" + bare + "/package.json");
pkg.name = pkgName;
pkg.description = pkgName + " - generated from the rbxts package template.";
pkg.homepage = repoUrl;
pkg.bugs = { url: repoUrl + "/issues" };
pkg.repository = { type: "git", url: repoUrl };
if (Array.isArray(pkg.keywords)) pkg.keywords = pkg.keywords.map((k) => k === "example" ? bare : k);
write("packages/" + bare + "/package.json", pkg);
const test = read("test/" + bare + "/package.json");
test.name = testName;
if (test.devDependencies && test.devDependencies["@lisachandra/example"]) {
  delete test.devDependencies["@lisachandra/example"];
  test.devDependencies[pkgName] = "workspace:*";
}
write("test/" + bare + "/package.json", test);
const ts = read("tsconfig.json");
for (const ref of ts.references || []) {
  if (ref.path === "packages/example") ref.path = "packages/" + bare;
  if (ref.path === "test/example") ref.path = "test/" + bare;
}
write("tsconfig.json", ts);
const testTs = read("test/" + bare + "/tsconfig.json");
for (const ref of testTs.references || []) {
  if (ref.path === "../../packages/example") ref.path = "../../packages/" + bare;
}
write("test/" + bare + "/tsconfig.json", testTs);
const ch = read(".changeset/config.json");
if (Array.isArray(ch.changelog) && ch.changelog[1] && typeof ch.changelog[1] === "object") {
  ch.changelog[1].repo = e.WZ_GH_OWNER + "/" + e.WZ_GH_REPO;
}
write(".changeset/config.json", ch);
const pj = read("packages/" + bare + "/default.project.json");
pj.name = bare;
write("packages/" + bare + "/default.project.json", pj);
const proj = read("test/" + bare + "/default.project.json");
proj.name = bare;
const nm = proj.tree && proj.tree.ReplicatedStorage && proj.tree.ReplicatedStorage.TS &&
  proj.tree.ReplicatedStorage.TS.rbxts_include && proj.tree.ReplicatedStorage.TS.rbxts_include.node_modules;
if (nm && nm["@lisachandra"] && nm["@lisachandra"].example) {
  const example = nm["@lisachandra"].example;
  example["$path"] = "../../packages/" + bare + "/out";
  delete nm["@lisachandra"];
  if (scope) { if (!nm[scope]) nm[scope] = {}; nm[scope][bare] = example; }
  else { nm[bare] = example; }
}
const tsfolder = proj.tree && proj.tree.ReplicatedStorage && proj.tree.ReplicatedStorage.TS;
if (tsfolder && tsfolder["example:tests"]) {
  tsfolder[bare + ":tests"] = tsfolder["example:tests"];
  delete tsfolder["example:tests"];
}
write("test/" + bare + "/default.project.json", proj);
'
  wz_sed_inplace "s|@lisachandra/example|$PKG_NAME|g" \
    "packages/$bare/src/index.ts" \
    "packages/$bare/README.md" \
    "test/$bare/src/example.spec.ts"
  wz_sed_inplace "s|name: \"example\"|name: \"$bare\"|" "test/$bare/jest.config.ts"
  if [[ -f "test/$bare/src/example.spec.ts" && "$bare" != "example" ]]; then
    git mv "test/$bare/src/example.spec.ts" "test/$bare/src/$bare.spec.ts" 2>/dev/null || true
  fi
  say "Done."
  warn "Still manual: README/AGENTS.md text, cspell wordlist, author fields, badge links."
}

# Pick the template before the banner so the stage count is honest.
detect_template
if [[ -z "$TEMPLATE_KIND" ]]; then
  _clear
  printf '\n  %sWhich template are you setting up?%s\n' "$BOLD" "$RESET"
  say "  1 — rbxts-game-template (Roblox game)"
  say "  2 — rbxts-package-template (publishable npm packages)"
  printf '  %sChoice%s [1/2] ' "$BOLD" "$RESET"
  read -r _tmpl_choice || true
  case "$_tmpl_choice" in
    2|package|pkg) TEMPLATE_KIND="package" ;;
    *)             TEMPLATE_KIND="game" ;;
  esac
fi

if [[ "$TEMPLATE_KIND" == "package" ]]; then
  TOTAL_STAGES=12
  TOTAL_MINUTES=55
  WZ_TITLE="rbxts-package-template setup"
else
  TOTAL_STAGES=13
  TOTAL_MINUTES=65
  WZ_TITLE="rbxts-game-template setup"
fi

banner "$WZ_TITLE"

# ── 1. Prerequisites ─────────────────────────────────────────────────────
stage "Prerequisites" 3
say "Checking the tools the template needs."
if command -v git >/dev/null 2>&1; then
  note "git — found"
else
  warn "git — missing"
  open_url "https://git-scm.com/downloads"
fi
if command -v mise >/dev/null 2>&1; then
  note "mise — found (it pins node/pnpm/rojo/gh/jq and the Luau tools)"
else
  warn "mise — missing"
  open_url "https://mise.jdx.dev"
  note "Windows: winget install jdx.mise (or scoop install mise); see mise.jdx.dev for others."
fi
if command -v pnpm >/dev/null 2>&1; then
  note "pnpm — found"
else
  note "pnpm — will be installed by mise from mise.toml"
fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "gh — found and authenticated"
else
  warn "gh — missing or not authenticated (only needed for automatic gists/repo/secrets)"
  note "Install it at https://cli.github.com and run: gh auth login"
fi
if detect_studio; then
  note "Roblox Studio — found"
else
  warn "Roblox Studio — not detected (needed for pnpm test:local and Studio-backed tests)"
  open_url "https://create.roblox.com/landing"
fi
pause "Press Enter when the prerequisites are ready (install anything missing first)"

# ── 2. Template source ───────────────────────────────────────────────────
stage "Template source" 4
say "Where is the template? Paste a local path (Enter keeps this directory) or a git URL to clone."
ask TEMPLATE_DIR "Template path or URL"
TEMPLATE_DIR=$(normalize_path "$TEMPLATE_DIR")
if [[ "$TEMPLATE_DIR" == *://* || "$TEMPLATE_DIR" == git@* ]]; then
  local dir_name
  dir_name=$(printf '%s' "$TEMPLATE_DIR" | sed -E 's#.*/##; s/\.git$//')
  say "Cloning into ./$dir_name …"
  git clone --recurse-submodules "$TEMPLATE_DIR" "$dir_name"
  TEMPLATE_DIR="$dir_name"
elif [[ -z "$TEMPLATE_DIR" ]]; then
  TEMPLATE_DIR="$(pwd)"
fi
cd "$TEMPLATE_DIR"
if [[ "$TEMPLATE_KIND" == "game" && ! looks_like_game ]]; then
  warn "This doesn't look like rbxts-game-template (missing default.project.json/bedrock.config.ts/asphalt.toml)."
  pause "Press Enter to continue anyway, or Ctrl-C to abort"
fi
if [[ "$TEMPLATE_KIND" == "package" && ! looks_like_package ]]; then
  warn "This doesn't look like rbxts-package-template (missing packages/example or .changeset)."
  pause "Press Enter to continue anyway, or Ctrl-C to abort"
fi
note "Tip: rename the folder itself now if you want a different directory name (git doesn't track it)."
if [[ "${SKIP_MISE:-0}" != 1 && "${SKIP_INSTALL:-0}" != 1 ]] && command -v mise >/dev/null 2>&1; then
  say "Installing the pinned toolchain (mise install) — first run takes a few minutes…"
  if ! mise install; then warn "mise install had issues — continue anyway and fix tool versions later."; fi
else
  note "Skipping mise install (SKIP_MISE/SKIP_INSTALL set, or mise not found)."
fi

# ── 3. Project identity ──────────────────────────────────────────────────
if [[ "$TEMPLATE_KIND" == "game" ]]; then
  stage "Project identity" 4
  say "These names are written into package.json, bedrock.config.ts, the UI, and asphalt.toml."
  ask PKG_NAME "npm package name (slug, e.g. my-cool-game)"
  [[ -z "$PKG_NAME" ]] && PKG_NAME=$(basename "$(pwd)")
  PKG_NAME=$(slugify "$PKG_NAME")
  ask DISPLAY_NAME "Roblox experience display name"
  [[ -z "$DISPLAY_NAME" ]] && DISPLAY_NAME="$PKG_NAME"
  DISPLAY_NAME=$(printf '%s' "$DISPLAY_NAME" | sed -e 's/["\\]//g' -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')
  ask CREATOR_ID "Your Roblox user id (number)"
  note "Find it in your profile URL: roblox.com/users/<id>/profile"
  CREATOR_ID=$(printf '%s' "$CREATOR_ID" | tr -dc '0-9')
  ask GH_OWNER "GitHub owner (user or org)"
  ask GH_REPO "GitHub repository name"
  [[ -z "$GH_REPO" ]] && GH_REPO="$PKG_NAME"
  GH_REPO=$(slugify "$GH_REPO")
else
  stage "Package identity" 4
  say "The template ships packages/example + test/example; this wizard renames them."
  ask PKG_NAME "npm package name (e.g. my-pkg or @scope/my-pkg)"
  if [[ "$PKG_NAME" == @*/* ]]; then
    WZ_SCOPE="${PKG_NAME%%/*}"
    WZ_BARE=$(slugify "${PKG_NAME#*/}")
  else
    WZ_SCOPE=""
    WZ_BARE=$(slugify "$PKG_NAME")
  fi
  [[ -z "$WZ_BARE" ]] && WZ_BARE=$(slugify "$(basename "$(pwd)")")
  PKG_NAME="${WZ_SCOPE:+$WZ_SCOPE/}$WZ_BARE"
  ask GH_OWNER "GitHub owner (user or org)"
  ask GH_REPO "GitHub repository name"
  [[ -z "$GH_REPO" ]] && GH_REPO="$WZ_BARE"
  GH_REPO=$(slugify "$GH_REPO")
fi
GH_OWNER=$(printf '%s' "$GH_OWNER" | tr -dc 'A-Za-z0-9._-')

# ── 4. Roblox experience ids ─────────────────────────────────────────────
stage "Roblox experience" 5
say "Open Cloud tests (and Bedrock deploys for games) need a universe and a place."
open_url "https://create.roblox.com/dashboard/creations"
step "Create a new experience, or open one you already own."
step "On its Configure page, copy the universe id from the URL (…/experiences/<id>/…)."
step "Under Places, copy the main place id."
ask UNIVERSE_ID "Roblox universe id"
ask PLACE_ID "Roblox place id"
UNIVERSE_ID=$(printf '%s' "$UNIVERSE_ID" | tr -dc '0-9')
PLACE_ID=$(printf '%s' "$PLACE_ID" | tr -dc '0-9')
write_env ROBLOX_UNIVERSE_ID "$UNIVERSE_ID"
write_env ROBLOX_PLACE_ID "$PLACE_ID"

# ── 5. Open Cloud API key ────────────────────────────────────────────────
stage "Open Cloud API key" 7
if [[ "$TEMPLATE_KIND" == "game" ]]; then
  say "Create one key with these scopes:"
  say "  universe-places:write"
  say "  universe.place.luau-execution-session:write"
  say "  universe-place, universe-place-config, universe-passes"
  say "  universe-developer-products, asset-create, asset:read, asset:write"
else
  say "Create one key with these scopes:"
  say "  universe-places:write"
  say "  universe.place.luau-execution-session:write"
fi
open_url "https://create.roblox.com/dashboard/credentials"
step "API keys → Create API key, select your experience, add the scopes above."
step "Choose an expiration, then copy the key (it is shown only once)."
ask_secret ROBLOX_OPEN_CLOUD_API_KEY "Paste the Open Cloud API key"
write_env ROBLOX_OPEN_CLOUD_API_KEY "$ROBLOX_OPEN_CLOUD_API_KEY"
if [[ "$TEMPLATE_KIND" == "game" ]]; then
  if confirm "Reuse this key for Bedrock and Asphalt too (recommended)"; then
    BEDROCK_API_KEY="$ROBLOX_OPEN_CLOUD_API_KEY"
    ASPHALT_API_KEY="$ROBLOX_OPEN_CLOUD_API_KEY"
  else
    ask_secret BEDROCK_API_KEY "Bedrock API key (same scopes)"
    ask_secret ASPHALT_API_KEY "Asphalt API key (asset:read + asset:write)"
  fi
  write_env BEDROCK_API_KEY "$BEDROCK_API_KEY"
  write_env ASPHALT_API_KEY "$ASPHALT_API_KEY"
fi

# ── 6. CI badge gist (optional) ──────────────────────────────────────────
if [[ "${SKIP_GITHUB:-0}" == 1 ]]; then
  note "SKIP_GITHUB=1 — skipping badge gist, Bedrock gist, and GitHub setup."
else
  stage "CI badge gist" 5
  if confirm "Set up README status badges (needs a private gist + a GitHub PAT with the gist scope)"; then
    say "Creating a private gist for the badges…"
    BADGE_GIST_ID=$(create_secret_gist "rbxts template CI badges" "badges.json" "{}" || true)
    if [[ -z "$BADGE_GIST_ID" ]]; then
      open_url "https://gist.github.com"
      step "Create a secret gist with any file, then copy the id from its URL."
      ask BADGE_GIST_ID "Badge gist id"
    else
      note "Created gist id: $BADGE_GIST_ID"
    fi
    open_url "https://github.com/settings/tokens/new?scopes=gist&description=rbxts-template-badges"
    step "Generate a classic PAT with the gist scope (or reuse an existing one)."
    ask_secret GIST_SECRET "GitHub PAT with gist scope"
    note "The CI workflow reads vars.BADGE_GIST_ID and secrets.GIST_SECRET."
  fi
fi

# ── 7. Bedrock gist (game) / npm token (package) ─────────────────────────
if [[ "$TEMPLATE_KIND" == "game" ]]; then
  if [[ "${SKIP_GITHUB:-0}" != 1 ]]; then
    stage "Bedrock state gist" 4
    say "Bedrock keeps deployment state in a private gist."
    say "Creating a private gist…"
    BEDROCK_GIST_ID=$(create_secret_gist "Bedrock state" "state.json" "{}" || true)
    if [[ -z "$BEDROCK_GIST_ID" ]]; then
      open_url "https://gist.github.com"
      step "Create a secret gist (a state.json containing {} is fine) and copy its id."
      ask BEDROCK_GIST_ID "Bedrock state gist id"
    else
      note "Created gist id: $BEDROCK_GIST_ID"
    fi
    if [[ -n "$GIST_SECRET" ]] && confirm "Reuse the badge PAT as BEDROCK_GITHUB_TOKEN (recommended)"; then
      BEDROCK_GITHUB_TOKEN="$GIST_SECRET"
    else
      open_url "https://github.com/settings/tokens/new?scopes=gist&description=bedrock-state"
      step "Generate a classic PAT with the gist scope."
      ask_secret BEDROCK_GITHUB_TOKEN "GitHub PAT for the Bedrock state gist"
    fi
    write_env BEDROCK_GITHUB_TOKEN "$BEDROCK_GITHUB_TOKEN"
  fi
else
  stage "npm publish token" 3
  open_url "https://www.npmjs.com/settings/${GH_OWNER:-you}/tokens"
  step "Generate a new token with publish access (or Granular Access on your packages)."
  ask_secret NPM_TOKEN "npm token"
  write_env NPM_TOKEN "$NPM_TOKEN"
fi

# ── 8. GitHub repository ─────────────────────────────────────────────────
if [[ "${SKIP_GITHUB:-0}" == 1 ]]; then
  note "SKIP_GITHUB=1 — skipping GitHub repository and CI secrets (set them later with gh)."
else
  stage "GitHub repository" 6
  export GH_REPO_FULL="${GH_OWNER}/${GH_REPO}"
  export GH_REPO="$GH_REPO_FULL"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh repo view "$GH_REPO_FULL" >/dev/null 2>&1; then
      note "Repository $GH_REPO_FULL already exists."
    else
      if confirm "Create $GH_REPO_FULL as a private repo on GitHub and push this branch"; then
        if git remote get-url origin >/dev/null 2>&1 && [[ "$(git remote get-url origin)" != *"$GH_REPO_FULL"* ]]; then
          if confirm "Repoint the existing 'origin' remote at your new repo"; then
            git remote set-url origin "https://github.com/$GH_REPO_FULL.git"
          fi
        fi
        if ! gh repo create "$GH_REPO_FULL" --private --source . --push; then
          warn "Couldn't create the repo automatically."
          open_url "https://github.com/new"
          step "Create it there, then push: git push -u origin HEAD"
          pause "Press Enter once the repo exists and is pushed"
        fi
      else
        open_url "https://github.com/new"
        step "Create the repo, then push: git push -u origin HEAD"
        pause "Press Enter once the repo exists and is pushed"
      fi
    fi
  else
    open_url "https://github.com/new"
    step "Create the repo, then push: git push -u origin HEAD"
    pause "Press Enter once the repo exists and is pushed"
  fi

  # ── 9. GitHub CI secrets & variables ────────────────────────────────────
  stage "GitHub CI secrets & variables" 4
  say "These match the secrets.* / vars.* references in .github/workflows/ci.yaml."
  set_secret ROBLOX_OPEN_CLOUD_API_KEY "$ROBLOX_OPEN_CLOUD_API_KEY"
  set_secret ROBLOX_PLACE_ID "$PLACE_ID"
  set_secret ROBLOX_UNIVERSE_ID "$UNIVERSE_ID"
  if [[ -n "$GIST_SECRET" ]]; then
    set_secret GIST_SECRET "$GIST_SECRET"
  fi
  if [[ -n "$BADGE_GIST_ID" ]]; then
    set_var BADGE_GIST_ID "$BADGE_GIST_ID"
  fi
  if [[ "$TEMPLATE_KIND" == "package" && -n "$NPM_TOKEN" ]]; then
    set_secret NPM_TOKEN "$NPM_TOKEN"
  fi
fi

# ── 10. Apply the rename ─────────────────────────────────────────────────
stage "Apply project rename" 5
if confirm "Write these names and ids into the template files now"; then
  if [[ "$TEMPLATE_KIND" == "game" ]]; then
    rename_game
  else
    rename_package
  fi
else
  note "Skipped — the template keeps its placeholder names."
fi

# ── 11. Install & build ──────────────────────────────────────────────────
stage "Install & build" 20
if [[ "${SKIP_INSTALL:-0}" == 1 ]]; then
  note "SKIP_INSTALL=1 — skipping dependency install and build."
else
  if [[ "$TEMPLATE_KIND" == "package" && "$WZ_BARE" != "example" ]]; then
    say "Renaming changed the workspace, so installing without --frozen-lockfile to refresh it."
    if ! wz_run pnpm install; then
      warn "pnpm install failed — fix the errors above, then run it again."
      pause "Press Enter to continue"
    fi
    if ! wz_run pnpm build; then
      warn "pnpm build failed — fix the errors above, then run pnpm build again."
      pause "Press Enter to continue"
    fi
  else
    say "Running pnpm setup (submodules + frozen install + build) — this takes a while."
    if ! wz_run pnpm setup; then
      warn "pnpm setup failed — fix the errors above, then run pnpm setup again."
      pause "Press Enter to continue"
    fi
  fi
  note "Next: pnpm dev (watch), pnpm serve (Rojo → Studio, game only), pnpm test (jest-roblox)."
fi

# ── 12. Codex agent hooks (optional) ─────────────────────────────────────
stage "Codex agent hooks" 2
if confirm "Junction .agents to your global agent config (recommended for Codex)"; then
  if [[ -e ".agents" ]]; then
    note ".agents already exists — nothing to do."
  else
    if [[ -n "$AGENT_CONFIG_DIR" ]]; then :; fi
    if [[ "$(uname -s)" == MINGW* || "$(uname -s)" == MSYS* || "$(uname -s)" == CYGWIN* ]]; then
      AGENT_CONFIG_DIR="${USERPROFILE:-$HOME}/.agents"
    else
      AGENT_CONFIG_DIR="$HOME/.agents"
    fi
    ask AGENT_CONFIG_DIR "Global agent config directory"
    AGENT_CONFIG_DIR=$(normalize_path "$AGENT_CONFIG_DIR")
    if [[ -d "$AGENT_CONFIG_DIR" ]]; then
      if [[ "$(uname -s)" == MINGW* || "$(uname -s)" == MSYS* || "$(uname -s)" == CYGWIN* ]]; then
        local win_path
        win_path=$(cygpath -w "$AGENT_CONFIG_DIR" 2>/dev/null || printf '%s' "$AGENT_CONFIG_DIR")
        if cmd //c mklink /J .agents "$win_path" >/dev/null 2>&1; then
          note "Created .agents junction → $AGENT_CONFIG_DIR"
        else
          warn "Couldn't create the junction automatically."
          note "Run: mklink /J .agents $win_path"
        fi
      else
        ln -s "$AGENT_CONFIG_DIR" .agents && note "Created .agents → $AGENT_CONFIG_DIR"
      fi
    else
      warn "$AGENT_CONFIG_DIR doesn't exist — skipping."
      note "Run later: mklink /J .agents <path> (Windows) or ln -s ~/.agents .agents (Unix)."
    fi
  fi
else
  note "Skipped — run later: mklink /J .agents <path> (Windows) or ln -s ~/.agents .agents (Unix)."
fi

finish

printf '\n  %sNext steps%s\n' "$BOLD" "$RESET"
note "  pnpm dev    — watch source + sourcemap"
note "  pnpm serve  — Rojo serve for Studio (game only)"
note "  pnpm test   — jest-roblox (needs Studio or the Open Cloud key)"
printf '\n'
